// Typed access to the extracted original data (src/core/data/gameData.json, regenerated by tools/extract-data.mjs).
import raw from './data/gameData.json';
import type { DieDef, EnemyCfg, RelicDef } from './types';

export interface ClassDef {
  id: string; name: string; title: string; desc: string; drawCount: number; maxPlays: number; freeRerolls: number;
  canBloodReroll: boolean; keepUnplayed: boolean; hp: number; maxHp: number; initialDice: string[]; passive: string; multi?: boolean;
}

export const DATA = raw as unknown as {
  classes: Record<string, ClassDef>;
  dice: Record<string, DieDef>;
  relics: Record<string, RelicDef>;
  enemies: Record<string, EnemyCfg>;
};

export function dieDef(id: string): DieDef {
  const d = DATA.dice[id]; if (!d) throw new Error('unknown die ' + id); return d;
}
export function enemyCfg(id: string): EnemyCfg {
  const e = DATA.enemies[id]; if (!e) throw new Error('unknown enemy ' + id); return e;
}
